Step.StepText:
Set Variable [ $resultPortal; Value:Let ( [

// Unique portals that are not already an account, straight out of the index.
// Replaces pulling all 7,153 PrinterPresence rows over OData on every load.
~rows = ExecuteSQL ( "SELECT DISTINCT \"portal\", \"number\" FROM \"PrinterPresence\" WHERE \"portal\" IS NOT NULL AND \"portal\" NOT IN ( SELECT \"Name\" FROM \"Account\" WHERE \"Name\" IS NOT NULL ) AND ( \"number\" IS NULL OR \"number\" NOT IN ( SELECT CAST(\"AccountNumber\" AS INT) FROM \"Account\" WHERE \"AccountNumber\" IS NOT NULL ) ) ORDER BY \"portal\"" ; Char ( 9 ) ; Char ( 13 ) ) ;

// ExecuteSQL answers "?" on a syntax or privilege error - never a portal list
~ok = not IsEmpty ( ~rows ) and Left ( ~rows ; 1 ) ≠ "?"

] ;

If ( not ~ok ; "{\"value\":[]}" ;

"{\"value\":[" &
While (
	[ ~n = ValueCount ( ~rows ) ; ~i = 1 ; ~out = "" ] ;
	~i ≤ ~n ;
	[ ~cells  = Substitute ( GetValue ( ~rows ; ~i ) ; Char ( 9 ) ; ¶ ) ;
	  ~portal = GetValue ( ~cells ; 1 ) ;
	  ~num    = GetValue ( ~cells ; 2 ) ;
	  ~obj    = JSONSetElement ( "{}" ; "portal" ; ~portal ; JSONString ) ;
	  ~obj    = If ( IsEmpty ( ~num ) ;
	                 JSONSetElement ( ~obj ; "number" ; "null" ; JSONRaw ) ;
	                 JSONSetElement ( ~obj ; "number" ; ~num ; JSONNumber ) ) ;
	  ~out    = ~out & If ( ~i > 1 ; "," ) & ~obj ;
	  ~i      = ~i + 1 ] ;
	~out
)
& "]}"

) ) ]

